async function runHuancaiDue(db, t, random = randomInt) {
  if (B19_HUANCAI_RETIRED) { await b19RetireHuancai(db, t, random); return; }
  const started = Date.now(), maxBatches = 12, maxMs = 1e4;
  for (let i = 0; i < maxBatches; i++) {
    await settleHuancai(db, t, random);
    const pending = await db.prepare("SELECT closes_at FROM huancai_rounds WHERE state='drawing' OR (state='open' AND closes_at<=?) ORDER BY closes_at LIMIT 1").bind(t).first();
    if (!pending) return;
    if (i === maxBatches - 1 || Date.now() - started >= maxMs) {
      if (t - pending.closes_at >= 240) console.warn("huancai_settlement_delayed", { delay_seconds: t - pending.closes_at });
      return;
    }
  }
}
function expandCompound(raw) {
  const x = raw;
  if (!x || !Array.isArray(x.front) || !Array.isArray(x.back)) throw new HuancaiError("\u8BF7\u9009\u62E9\u590D\u5F0F\u53F7\u7801");
  for (const [a, min, max] of [[x.front, 5, 35], [x.back, 2, 12]]) if (a.length < min || a.length > max || new Set(a).size !== a.length || a.some((n) => !Number.isInteger(n) || n < 1 || n > max)) throw new HuancaiError("\u590D\u5F0F\u53F7\u7801\u6570\u91CF\u3001\u8303\u56F4\u6216\u91CD\u590D\u9879\u4E0D\u6B63\u786E");
  const choose = (a, k) => {
    let n = 1;
    for (let i = 1; i <= k; i++) n = n * (a.length - i + 1) / i;
    return n;
  };
  if (choose(x.front, 5) * choose(x.back, 2) > 100) throw new HuancaiError("\u5355\u6B21\u590D\u5F0F\u6700\u591A100\u6CE8\uFF0C\u8BF7\u51CF\u5C11\u53F7\u7801");
  const combinations = (a, k) => {
    const out = [];
    const visit = (start, selected) => {
      if (selected.length === k) {
        out.push(selected);
        return;
      }
      for (let i = start; i <= a.length - (k - selected.length); i++) visit(i + 1, [...selected, a[i]]);
    };
    visit(0, []);
    return out;
  };
  const front = [...x.front].sort((a, b) => a - b), back = [...x.back].sort((a, b) => a - b);
  return combinations(front, 5).flatMap((f) => combinations(back, 2).map((b) => ({ front: f, back: b })));
}
const LOTTO_FIXED_PRIZES={1:5200000,2:520000,3:52000,4:5200,5:520,6:52,7:12};
function fixedJackpotPayout(tier, counts, pool) {
  if (!LOTTO_FIXED_PRIZES[tier] || !counts[tier]) return 0;
  const demand = Object.entries(LOTTO_FIXED_PRIZES).reduce((n, [k, v]) => n + BigInt(counts[k] || 0) * BigInt(v), 0n);
  const reserve = BigInt(pool);
  return Number(BigInt(LOTTO_FIXED_PRIZES[tier]) * (demand < reserve ? demand : reserve) / demand);
}
function guessAdmissionSql(questions, uid, at, roomId = "0") {
  return `NOT EXISTS(SELECT 1 FROM guess_room_messages busy
  WHERE busy.packet_id=p.packet_id AND busy.user_id=${uid} AND busy.deleted=0
  AND (busy.ai_status IS NULL OR busy.ai_status='pending') AND busy.created_at>${at}-45 AND busy.id<>${roomId})
  AND NOT EXISTS(SELECT 1 FROM ${questions} pending
  WHERE pending.packet_id=p.packet_id AND pending.user_id=${uid} AND pending.verdict='pending' AND pending.created_at>${at}-45)`;
}
async function rejectPendingGuess(c, p, u, roomId = 0) {
  const at = now(), tables = gameTables(p);
  const busy = await c.env.DB.prepare(`SELECT 1 FROM ${tables.rounds} p WHERE p.packet_id=?1 AND NOT (${guessAdmissionSql(tables.questions, "?2", "?3", "?4")})`).bind(p.packet_id, u.id, at, roomId).first();
  if (!busy) return;
  const day = new Date((p.created_at + 28800) * 1e3).toISOString().slice(0, 10);
  await c.env.DB.prepare("INSERT OR IGNORE INTO quota_usage(day,scope,key,n) VALUES(?,?,?,1)").bind(day, "guess:overlap:" + p.packet_id, u.id).run().catch(() => console.error("guess_overlap_observation_failed"));
  c.header("Retry-After", "2");
  fail(429, "\u4E0A\u4E00\u6761\u731C\u8BCD\u6216\u63D0\u95EE\u4ECD\u5728\u5904\u7406\uFF0C\u8BF7\u7B49\u5F85\u7ED3\u679C\u540E\u518D\u53D1\u9001\u3002", "guess_pending");
}
async function guessSubmissionSignals(c) {
  const day = new Date((now() - 7 * 86400 + 28800) * 1e3).toISOString().slice(0, 10);
  const rows = await c.env.DB.prepare(`SELECT s.scope,s.day,u.id AS user_id,COALESCE(u.nick,u.name,u.username) AS name,u.avatar
  FROM (SELECT key,scope,day FROM quota_usage WHERE scope GLOB 'guess:overlap:*' AND day>=? ORDER BY day DESC,scope,key LIMIT 50) s
  LEFT JOIN users u ON u.id=s.key
  ORDER BY s.day DESC,s.scope,s.key`).bind(day).all();
  return { items: rows.results.map(({ scope, ...r }) => ({ ...r, packet_id: scope.slice("guess:overlap:".length) })), notice: "\u540C\u8D26\u53F7\u540C\u5C40\u5E76\u53D1\u63D0\u4EA4\u7684\u9996\u6B21\u8BB0\u5F55\uFF0C\u4EC5\u4F9B\u6392\u67E5\uFF1B\u7F51\u7EDC\u91CD\u8BD5\u3001\u591A\u6807\u7B7E\u7B49\u4E5F\u53EF\u80FD\u89E6\u53D1\uFF0C\u4E0D\u4EE3\u8868\u4F7F\u7528\u4E86AI\uFF0C\u4E0D\u81EA\u52A8\u5904\u7F5A\u3002", retention_days: 60 };
}

