  var BABY_PERSONAL_EVENTS = Array.from({ length: 24 }, (_, i) => ({ id: `baby-personal-${i}`, title: ["\u5206\u4EAB\u70B9\u5FC3", "\u7B2C\u4E00\u6B21\u9053\u6B49", "\u6536\u597D\u73A9\u5177", "\u964C\u751F\u7684\u8BBF\u5BA2", "\u5B88\u4F4F\u7EA6\u5B9A", "\u7167\u987E\u5C0F\u82D7", "\u665A\u5B89\u6545\u4E8B", "\u627E\u56DE\u94C3\u94DB", "\u96E8\u5929\u6563\u6B65", "\u8F6E\u6D41\u6E38\u620F", "\u52C7\u6562\u53D1\u95EE", "\u81EA\u5DF1\u7684\u540D\u5B57"][i % 12] + (i >= 12 ? "\xB7\u957F\u5927\u4EE5\u540E" : ""), text: ["\u5B83\u628A\u6700\u540E\u4E00\u5757\u70B9\u5FC3\u63A8\u7ED9\u540C\u4F34\uFF0C\u53C8\u6084\u6084\u770B\u5411\u4F60\u3002", "\u73A9\u5177\u78B0\u5012\u4E86\u82B1\u76C6\uFF0C\u5B83\u8EB2\u5728\u53F6\u5B50\u540E\u9762\u4E0D\u6562\u51FA\u6765\u3002", "\u5B83\u53D1\u73B0\u6574\u7406\u597D\u7684\u73A9\u5177\u66F4\u5BB9\u6613\u627E\u5230\uFF0C\u5374\u820D\u4E0D\u5F97\u7ED3\u675F\u6E38\u620F\u3002", "\u4E00\u4F4D\u964C\u751F\u8BBF\u5BA2\u6765\u5230\u56F4\u680F\u8FB9\uFF0C\u5B83\u4E0D\u77E5\u9053\u8BE5\u9760\u8FD1\u8FD8\u662F\u8EB2\u5F00\u3002", "\u5B83\u7B54\u5E94\u7B49\u540C\u4F34\u56DE\u6765\uFF0C\u5348\u7761\u65F6\u95F4\u5374\u5DF2\u7ECF\u5230\u4E86\u3002", "\u5C0F\u82D7\u7684\u53F6\u5B50\u5782\u4E86\u4E0B\u6765\uFF0C\u5B83\u63D0\u8D77\u4E86\u6BD4\u81EA\u5DF1\u8FD8\u9AD8\u7684\u6C34\u58F6\u3002", "\u6545\u4E8B\u8BB2\u5230\u8FF7\u8DEF\u7684\u65C5\u4EBA\uFF0C\u5B83\u575A\u6301\u8981\u542C\u5230\u65C5\u4EBA\u56DE\u5BB6\u3002", "\u8349\u4E1B\u91CC\u54CD\u8D77\u522B\u4EBA\u7684\u94C3\u94DB\uFF0C\u5B83\u62B1\u7740\u94C3\u94DB\u5BFB\u627E\u4E3B\u4EBA\u3002", "\u96E8\u505C\u540E\u7684\u5730\u9762\u5F88\u6ED1\uFF0C\u5B83\u4F38\u51FA\u8EAB\u4F53\u60F3\u7275\u4F4F\u4F60\u3002", "\u4E24\u53EA\u5E7C\u4F53\u90FD\u60F3\u73A9\u540C\u4E00\u4E2A\u7403\uFF0C\u5B83\u770B\u7740\u4F60\u7B49\u5F85\u7B54\u6848\u3002", "\u5B83\u4E3E\u8D77\u5C0F\u624B\uFF0C\u60F3\u77E5\u9053\u4E3A\u4EC0\u4E48\u51B0\u548C\u706B\u4E5F\u80FD\u6210\u4E3A\u670B\u53CB\u3002", "\u5B83\u628A\u81EA\u5DF1\u7684\u540D\u5B57\u5199\u5728\u53F6\u5B50\u4E0A\uFF0C\u60F3\u8D34\u5728\u95E8\u8FB9\u3002"][i % 12], choices: ["\u9F13\u52B1\u5B83\u8868\u8FBE\u81EA\u5DF1\u7684\u60F3\u6CD5", "\u966A\u5B83\u8003\u8651\u540C\u4F34\u7684\u611F\u53D7"] }));

