async function ensureFolders(c, uid) {
	const list = () => c.env.DB.prepare(`SELECT f.id, f.name, f.sort, (SELECT COUNT(*) FROM favorites v WHERE v.folder_id = f.id) AS n
     FROM fav_folders f WHERE f.user_id = ? ORDER BY f.sort, f.id`).bind(uid).all().then((r) => r.results);
	const got = await list();
	if (got.length) return got;
	await c.env.DB.batch(DEFAULT_FOLDERS.map((name, i) => c.env.DB.prepare("INSERT OR IGNORE INTO fav_folders (user_id, name, sort, created_at) VALUES (?, ?, ?, ?)").bind(uid, name, i, now())));
	return list();
}
