var ACTS = {
	fav: (folder) => [`SELECT meme_id, 'fav' AS kind, NULL AS val, NULL AS ref, MAX(created_at) AS at FROM favorites
     WHERE user_id = ?${folder ? " AND folder_id = ?" : ""} GROUP BY meme_id`, folder ? [folder] : []],
	like: () => [`SELECT meme_id, 'like' AS kind, NULL AS val, NULL AS ref, created_at AS at FROM likes WHERE user_id = ?`, []],
	reply: () => [`SELECT meme_id, 'reply' AS kind, text AS val, NULL AS ref, created_at AS at FROM short_replies WHERE user_id = ?
     UNION ALL SELECT meme_id, 'emoji', emoji, NULL, created_at FROM reactions WHERE user_id = ?`, ["@uid"]],
	comment: () => [`SELECT meme_id, 'comment' AS kind, body AS val, id AS ref, created_at AS at FROM comments WHERE user_id = ? AND deleted = 0`, []],
	post: () => [`SELECT id AS meme_id, 'post' AS kind, NULL AS val, NULL AS ref, created_at AS at FROM memes WHERE author_id = ?`, []],
	seen: () => [`SELECT meme_id, 'seen' AS kind, NULL AS val, NULL AS ref, seen_at AS at FROM views WHERE user_id = ?`, []]
};
app.get("/api/me/items", async (c) => {
	const u = needUser(c);
	const [sql, extra] = (ACTS[c.req.query("tab") ?? "fav"] ?? fail(400, "未知分类"))(intIn(c.req.query("folder"), 0, Number.MAX_SAFE_INTEGER, 0) || null);
	const actArgs = [u.id, ...extra.map((v) => v === "@uid" ? u.id : v)];
	const page = intIn(c.req.query("page"), 1, 1e3, 1);
	const size = 20;
	const where = ["m.hidden = 0"];
	const args = [];
	const q = (c.req.query("q") ?? "").trim();
	if (q) {
		const like = `%${q.replace(/[\\%_]/g, (s) => "\\" + s)}%`;
		where.push(`(m.title LIKE ? ESCAPE '\\' OR m.content LIKE ? ESCAPE '\\' OR a.val LIKE ? ESCAPE '\\')`);
		args.push(like, like, like);
	}
	const order = c.req.query("sort") === "old" ? "a.at ASC" : "a.at DESC";
	const from = `(${sql}) a JOIN memes m ON m.id = a.meme_id LEFT JOIN users u ON u.id = m.author_id WHERE ${where.join(" AND ")}`;
	const [rows, total] = await Promise.all([c.env.DB.prepare(`SELECT ${MEME_COLS}, a.kind AS act_kind, a.val AS act_val, a.ref AS act_ref, a.at AS act_at
       FROM ${from} ORDER BY ${order}, m.id DESC LIMIT ? OFFSET ?`).bind(...actArgs, ...args, 21, (page - 1) * size).all(), c.env.DB.prepare(`SELECT COUNT(*) AS n FROM ${from}`).bind(...actArgs, ...args).first()]);
	const list = rows.results.slice(0, size);
	const items = await decorate(c, list);
	return c.json({
		items: items.map((it, i) => ({
			...it,
			act: {
				kind: list[i].act_kind,
				val: list[i].act_val?.slice(0, 200) ?? null,
				ref: list[i].act_ref,
				at: list[i].act_at
			}
		})),
		more: rows.results.length > size,
		total: total?.n ?? 0
	});
});
