app.put("/api/admin/users/:id/limits", async (c) => {
	const { me, t } = await adminTarget(c);
	const b = await jsonBody(c);
	const kind = String(b.kind ?? "");
	if (!(kind in LIMIT_KINDS)) fail(400, "不认识的限制类型");
	const minutes = intIn(b.minutes, 0, 5256e3, 0);
	const until = minutes ? now() + minutes * 60 : 0;
	const reason = String(b.reason ?? "").trim().slice(0, 100) || null;
	await c.env.DB.prepare(`INSERT INTO user_limits (user_id, kind, until, reason, by_id, created_at) VALUES (?, ?, ?, ?, ?, ?)
     ON CONFLICT (user_id, kind) DO UPDATE SET until = excluded.until, reason = excluded.reason, by_id = excluded.by_id, created_at = excluded.created_at`).bind(t.id, kind, until, reason, me.id, now()).run();
	return c.json({
		ok: true,
		until
	});
});
