app.post("/api/memes/:id/comments", async (c) => {
	const u = needUser(c);
	if (u.silenced) fail(403, "你在 linux.do 处于禁言状态");
	await needNotLimited(c, u, "comment");
	const id = intIn(c.req.param("id"), 0, Number.MAX_SAFE_INTEGER, 0);
	const b = await jsonBody(c);
	const body = String(b.body ?? "").trim().slice(0, 1e3);
	if (!body) fail(400, "说点什么吧");
	if (!await c.env.DB.prepare("SELECT 1 FROM memes WHERE id = ? AND hidden = 0").bind(id).first()) fail(404, "不存在");
	const rid = intIn(b.reply_to, 0, Number.MAX_SAFE_INTEGER, 0);
	const parent = rid ? await c.env.DB.prepare("SELECT c.id, c.body, u.username, u.name FROM comments c JOIN users u ON u.id = c.user_id WHERE c.id = ? AND c.meme_id = ? AND c.deleted = 0").bind(rid, id).first() : null;
	const last = await c.env.DB.prepare("SELECT MAX(created_at) AS t FROM comments WHERE user_id = ?").bind(u.id).first();
	if (rateOn(c) && last?.t && now() - last.t < 5) fail(429, "慢一点，5 秒后再评论");
	const t = now();
	const [ins] = await c.env.DB.batch([c.env.DB.prepare("INSERT INTO comments (meme_id, user_id, body, reply_to, created_at) VALUES (?, ?, ?, ?, ?) RETURNING id").bind(id, u.id, body, parent?.id ?? null, t), c.env.DB.prepare("UPDATE memes SET comment_count = comment_count + 1 WHERE id = ?").bind(id)]);
	const cid = ins.results[0].id;
	return c.json({ comment: {
		id: cid,
		body,
		created_at: t,
		user_id: u.id,
		username: u.username,
		name: u.name,
		avatar: u.avatar,
		trust_level: u.trust_level,
		can_delete: true,
		reply_to: parent ? {
			id: parent.id,
			username: parent.username,
			name: parent.name,
			deleted: false,
			text: snippet(parent.body, 60)
		} : null
	} });
});
