var CHAT_PAGE = 40;
var CHAT_BODY_MAX = 2e3;
var CHAT_FIELDS = `x.*, u.username, u.name, u.avatar, u.trust_level, u.is_admin, u.fancy, u.deco`;
var CHAT_SELECT = `SELECT ${CHAT_FIELDS}
  FROM chat_messages x LEFT JOIN users u ON u.id = x.user_id`;
var CHAT_UPDATES_SELECT = `SELECT ${CHAT_FIELDS}
  FROM chat_messages x INDEXED BY idx_chat_msg_upd LEFT JOIN users u ON u.id = x.user_id`;
var CHAT_PACKET_SELECT = `SELECT ${CHAT_FIELDS}
  FROM chat_redpacks p CROSS JOIN chat_messages x ON x.id=p.message_id LEFT JOIN users u ON u.id=x.user_id`;
var BOOST_MAX = 12;
var chatPreview = (s, n = 60) => {
	const t = s.replace(/\[quote[^\]]*\][\s\S]*?\[\/quote\]/g, " ").replace(/\s+/g, " ").trim();
	return t.length > n ? t.slice(0, n) + "…" : t;
};
var chatRefText = (s, n = 600) => {
	const t = s.replace(/\[quote[^\]]*\][\s\S]*?\[\/quote\]/g, "").replace(/\n{3,}/g, "\n\n").trim();
	return t.length > n ? t.slice(0, n) + "…" : t;
};
var likeEsc = (s) => s.replace(/[\\%_]/g, (x) => "\\" + x);
var needAdmin = (c) => {
	const u = needUser(c);
	if (!isChatAdmin(u)) fail(403, "只有管理员能管理群组");
	return u;
};
var msgMedia = (m) => {
	if (!m.media) return null;
	try {
		return JSON.parse(m.media);
	} catch {
		return null;
	}
};
function chatMediaExpired(createdAt,hasMedia,at=Math.floor(Date.now()/1000)){return hasMedia && Number.isFinite(createdAt) && createdAt<=at-604800}
function refOf(r) {
	const expired=chatMediaExpired(r.created_at,!!(r.image_key||r.media));
	const first = expired ? null : msgMedia(r)?.[0];
	const file = first?.kind === "f" ? first : null;
	const pic = !expired && !r.deleted && !file && r.image_key ? `/img/${r.image_key}` : null;
	return {
		id: r.id,
		username: r.username,
		name: r.name,
		avatar: r.avatar,
		deleted: !!r.deleted,
		fancy: isFancy(r),
		deco: decoOf(r.deco),
		image: !!pic,
		thumb: pic,
		file: !r.deleted && file ? file.n ?? "文件" : null,
		media_expired:!r.deleted&&expired,
		text: r.deleted ? "" : chatRefText(r.body)
	};
}
var AT_RE = /(?<![\w@.])@([A-Za-z0-9_][\w.-]{0,30}[\w])/g;
var atNames = (body) => [...new Set([...chatRefText(body, 4e3).matchAll(AT_RE)].map((x) => x[1].toLowerCase()))].slice(0, 20);
async function atReads(c, rows) {
	const out = /* @__PURE__ */ new Map();
	const want = rows.filter((r) => !r.deleted && r.body?.includes("@")).map((r) => ({
		r,
		names: atNames(r.body)
	})).filter((x) => x.names.length);
	if (!want.length) return out;
	const gids = [...new Set(want.map((x) => x.r.group_id))];
	const names = [...new Set(want.flatMap((x) => x.names))];
	const { results } = await c.env.DB.prepare(`SELECT cm.group_id, lower(u.username) AS n, cm.last_read, cm.joined_at, ${CHAT_HISTORY_FLOOR} AS history_floor FROM json_each(?2) names
     CROSS JOIN users u ON u.username = names.value COLLATE NOCASE
     CROSS JOIN chat_members cm ON cm.user_id = u.id
     WHERE cm.group_id IN (SELECT value FROM json_each(?1))`).bind(JSON.stringify(gids), JSON.stringify(names)).all();
	const lr = new Map(results.map((x) => [x.group_id + ":" + x.n, x]));
	for (const { r, names: ns } of want) {
		const o = {};
		for (const n of ns) {
			const v = lr.get(r.group_id + ":" + n);
			if (v && r.created_at >= v.joined_at && r.id >= v.history_floor) o[n] = v.last_read >= r.id;
		}
		if (Object.keys(o).length) out.set(r.id, o);
	}
	return out;
}
// 匿名群（chat/1）：除站长外，消息里的发言者、引用、回应名单一律换成化名（services/identity-mask.ts）
async function decorateMsgs(c, rows) {
	const out = await decorateMsgsRaw(c, rows), viewer = c.get("user");
	return seesAnonGroup(c.env, viewer) ? out : maskChatMessages(c.env, viewer, out);
}
async function decorateMsgsRaw(c, rows) {
	if (!rows.length) return [];
	const u = c.get("user");
	const ids = JSON.stringify(rows.map((r) => r.id));
	const refs = JSON.stringify([...new Set(rows.map((r) => r.reply_to).filter(Boolean))]);
	const [reacts, quoted, boosts, reads, replied, road, packets] = await Promise.all([
		c.env.DB.prepare(`SELECT r.message_id, r.emoji, COUNT(*) AS n, MAX(r.user_id = ?) AS mine,
         (SELECT json_group_array(json_object('username', w.username, 'name', w.name, 'avatar', w.avatar))
          FROM (SELECT r2.user_id FROM chat_reactions r2 WHERE r2.message_id = r.message_id AND r2.emoji = r.emoji
                ORDER BY r2.created_at LIMIT 3) t JOIN users w ON w.id = t.user_id) AS who
       FROM chat_reactions r WHERE r.message_id IN (SELECT value FROM json_each(?)) GROUP BY r.message_id, r.emoji ORDER BY MIN(r.created_at)`).bind(u?.id ?? -1, ids).all(),
		refs === "[]" ? { results: [] } : c.env.DB.prepare(`SELECT x.id, x.group_id, x.body, x.image_key, x.media, x.created_at, x.deleted, u.username, u.name, u.avatar, u.is_admin, u.trust_level, u.fancy, u.deco
       FROM chat_messages x LEFT JOIN users u ON u.id = x.user_id
       WHERE x.id IN (SELECT value FROM json_each(?1))
       AND EXISTS(SELECT 1 FROM chat_members cm WHERE cm.group_id=x.group_id AND cm.user_id=?2 AND x.created_at>=cm.joined_at AND x.id>=${CHAT_HISTORY_FLOOR})
       AND EXISTS(SELECT 1 FROM chat_messages source WHERE source.id IN (SELECT value FROM json_each(?3)) AND source.reply_to=x.id AND source.group_id=x.group_id)`).bind(refs, u?.id ?? 0, ids).all(),
		c.env.DB.prepare(`SELECT b.message_id, b.text, b.user_id, b.created_at, b.ai_status, b.ai_score, u.kind, u.username, u.name, u.avatar, u.deco FROM chat_boosts b LEFT JOIN users u ON u.id = b.user_id
       WHERE b.message_id IN (SELECT value FROM json_each(?)) ORDER BY b.created_at`).bind(ids).all(),
		atReads(c, rows),
		c.env.DB.prepare(`SELECT x.reply_to AS id, COUNT(*) AS n FROM chat_messages x
       JOIN chat_members cm ON cm.group_id=x.group_id AND cm.user_id=?2
       WHERE x.reply_to IN (SELECT value FROM json_each(?1)) AND x.deleted=0
         AND x.created_at>=cm.joined_at AND x.id>=${CHAT_HISTORY_FLOOR} GROUP BY x.reply_to`).bind(ids, u?.id ?? 0).all(),
		c.env.DB.prepare("SELECT source_msg_id AS mid, id FROM road_items INDEXED BY idx_road_source_msg WHERE source_msg_id IN (SELECT value FROM json_each(?)) AND hidden = 0 AND source_hidden = 0").bind(ids).all(),
		rows.some((r) => !r.deleted && (r.redpack_id || sharedPacket(r.body))) ? c.env.DB.prepare(`SELECT p.message_id, p.mode, p.game, p.prompt, p.provider, p.notify_at, p.draw_data, COALESCE(lp.mode,fp.mode) AS ldc_mode, COALESCE(lp.room_revision,fp.room_revision) AS guess_revision, lp.total_cents AS ldc_total,lp.count AS ldc_count,lp.payment_provider AS payment_provider, COALESCE(lp.response_mode,fp.response_mode) AS ldc_response_mode, CASE WHEN COALESCE(lp.response_mode,fp.response_mode)='similarity' THEN COALESCE(lp.answer_length,fp.answer_length) ELSE NULL END AS ldc_answer_length, CASE WHEN cp.packet_id IS NOT NULL THEN json_object('state',CASE WHEN cp.expires_at<=unixepoch() THEN 'expired' WHEN cp.remaining_count=0 THEN 'exhausted' ELSE 'active' END,'claimed',EXISTS(SELECT 1 FROM coin52_packet_slots WHERE packet_id=p.id AND recipient_id=${u?.id ?? 0}),'remaining',cp.remaining_count,'total',cp.count,'claimed_count',cp.count-cp.remaining_count,'expires_at',cp.expires_at,'kind',cp.mode) ELSE v.data END AS snapshot, v.synced_at, o.solved_at,
       (SELECT COUNT(*) FROM chat_redpack_opens s WHERE s.packet_id=p.id AND s.solved_at IS NOT NULL) AS opened
       FROM chat_redpacks p LEFT JOIN chat_redpack_opens o ON o.packet_id=p.id AND o.user_id=?
       LEFT JOIN chat_redpack_external_views v ON v.packet_id=p.id AND v.user_id=?
       LEFT JOIN ldc_packets lp ON lp.packet_id=p.id
       LEFT JOIN guess_free_rounds fp ON fp.packet_id=p.id
       LEFT JOIN coin52_packets cp ON cp.packet_id=p.id
       WHERE p.message_id IN (SELECT value FROM json_each(?))`).bind(u?.id ?? 0, u?.id ?? 0, ids).all() : { results: [] }
	]);
	const packetMap = new Map(packets.results.map((p) => [p.message_id, {
		mode: p.mode,
		game: p.game,
		prompt: p.prompt,
		provider: p.provider,
		ldc_mode: p.ldc_mode,
		guess_revision: p.guess_revision,
		ldc_total: p.ldc_total,
        ldc_count: p.ldc_count,
		payment_provider: p.payment_provider,
		ldc_response_mode: p.ldc_response_mode,
		ldc_answer_length: p.ldc_answer_length,
		notify_at: p.notify_at,
		draw: p.draw_data ? JSON.parse(p.draw_data) : null,
		snapshot: packetSnapshotView(p.snapshot),
		synced_at: p.synced_at,
		solved: !!p.solved_at,
		opened: p.opened
	}]));
	const roadIds = new Map(road.results.map((r) => [r.mid, r.id]));
	const rc = new Map(replied.results.map((r) => [r.id, r.n]));
	const bs = /* @__PURE__ */ new Map();
	for (const b of boosts.results) {
		const ai = b.kind === "bot" && !!b.ai_status;
		bs.set(b.message_id, [...bs.get(b.message_id) ?? [], {
			deco: decoOf(b.deco),
			text: b.text,
			mine: !ai && !!u && u.id === b.user_id,
			username: b.username,
			name: ai ? "欢欢" : b.name,
			avatar: ai ? "/ai-avatar.svg" : b.avatar,
			at: b.created_at,
			ai,
			status: ai ? b.ai_status : "",
			score: ai ? b.ai_score : null
		}]);
	}
	const rx = /* @__PURE__ */ new Map();
	for (const r of reacts.results) {
		let who = [];
		try {
			who = JSON.parse(r.who || "[]");
		} catch {}
		rx.set(r.message_id, [...rx.get(r.message_id) ?? [], {
			emoji: r.emoji,
			count: r.n,
			mine: !!r.mine,
			who
		}]);
	}
	const q = new Map(quoted.results.map((r) => [r.id, r]));
	const phraseLocked = new Set(u && rows.some((r) => !r.deleted && r.user_id === u.id && r.body) ? (await c.env.DB.prepare(`SELECT DISTINCT m.id FROM json_each(?) j CROSS JOIN chat_messages m ON m.id=j.value WHERE m.user_id=? AND m.deleted=0 AND m.body<>'' AND EXISTS(SELECT 1 FROM chat_redpacks rp CROSS JOIN chat_messages rx ON rx.id=rp.message_id WHERE rp.phrase=m.body AND rp.mode='phrase' AND rx.group_id=m.group_id AND rx.id<m.id AND rx.deleted=0)`).bind(ids, u.id).all()).results.map((r) => r.id) : []);
	return rows.map((m) => {
		const r = m.reply_to ? q.get(m.reply_to) : null;
		const expired=chatMediaExpired(m.created_at,!!(m.image_key||m.media));
		return {
			id: m.id,
			group_id: m.group_id,
			deleted: !!m.deleted,
			system_kind: m.system_kind ?? null,
			system_ref: m.system_ref ?? null,
			body: m.deleted ? "" : m.body,
			image: m.deleted || expired || !m.image_key ? null : `/img/${m.image_key}`,
			width: m.width,
			height: m.height,
			media: m.deleted || expired ? null : msgMedia(m)?.map(toGallery) ?? null,
			media_expired:!m.deleted&&expired,
			created_at: m.created_at,
			updated_at: m.updated_at,
			edited_at: m.deleted ? null : m.edited_at ?? null,
			user: {
				id: m.user_id,
				username: m.username ?? "佚名",
				name: m.name,
				avatar: m.avatar,
				trust_level: m.trust_level ?? 0,
				is_admin: !!m.is_admin,
				fancy: isFancy(m),
				deco: decoOf(m.deco)
			},
			reply_to: r?.group_id === m.group_id ? refOf(r) : null,
			reply_count: rc.get(m.id) ?? 0,
			reactions: rx.get(m.id) ?? [],
			boosts: m.deleted ? [] : bs.get(m.id) ?? [],
			at_read: reads.get(m.id) ?? null,
			mine: !!u && u.id === m.user_id,
			can_delete: !m.deleted && !phraseLocked.has(m.id) && !m.redpack_id && !packetMap.has(m.id) && !sharedPacket(m.body) && !!u && (!m.system_kind && u.id === m.user_id || isChatAdmin(u)),
			can_edit: !m.deleted && !phraseLocked.has(m.id) && !m.redpack_id && !packetMap.has(m.id) && !sharedPacket(m.body) && !m.system_kind && !!u && u.id === m.user_id,
			redpack: m.deleted || !packetMap.has(m.id) ? null : {
				...packetMap.get(m.id),
				shared: !m.redpack_id,
				cover: !expired && m.redpack_id && m.image_key ? `/img/${m.image_key}` : null
			},
			meme_id: m.meme_id ?? null,
			road_id: m.deleted ? null : roadIds.get(m.id) ?? null
		};
	});
}
app.get("/api/chat/groups", async (c) => {
	const u = c.get("user");
	if (!u) return c.json({
		groups: [],
		gone: [],
		can_manage: false,
		dm_unread: 0
	});
	const gone = await c.env.DB.prepare(`SELECT g.id, g.name, g.is_default, b.kind, r.status AS req, EXISTS(SELECT 1 FROM chat_group_policy p WHERE p.group_id=g.id) AS internal, r.created_at AS req_at, EXISTS(SELECT 1 FROM chat_kick_notes n WHERE n.group_id=g.id AND n.user_id=?1 AND n.at>=b.created_at) AS idle FROM chat_groups g LEFT JOIN chat_bans b ON b.group_id=g.id AND b.user_id=?1
     LEFT JOIN chat_join_reqs r ON r.group_id=g.id AND r.user_id=?1
     WHERE (g.is_default=1 OR (b.user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chat_group_policy p WHERE p.group_id=g.id)) OR (b.user_id IS NULL AND EXISTS(SELECT 1 FROM chat_group_policy p WHERE p.group_id=g.id AND p.open_apply=1))) AND NOT EXISTS (SELECT 1 FROM chat_members m WHERE m.group_id=g.id AND m.user_id=?1)
     ORDER BY g.is_default DESC, b.created_at DESC`).bind(u.id).all();
	const pend = isChatAdmin(u) ? await c.env.DB.prepare(`SELECT group_id AS gid, COUNT(*) AS n FROM chat_join_reqs r WHERE status = 0 ${isOwner(c, u) ? "" : "AND COALESCE((SELECT trust_level FROM users WHERE id = r.user_id),0) < 4 AND r.group_id NOT IN (SELECT group_id FROM chat_group_policy)"} GROUP BY group_id`).all() : null;
	const pm = new Map((pend?.results ?? []).map((x) => [x.gid, x.n]));
	const { results } = await c.env.DB.prepare(`SELECT g.id, g.name, g.avatar, g.is_default, g.created_at, cm.last_read, cm.muted, g.notice, g.notice_at, (SELECT open_apply FROM chat_group_policy p WHERE p.group_id=g.id) AS internal_open,
       g.member_count-(SELECT COUNT(*) FROM chat_members bm JOIN users bu ON bu.id=bm.user_id WHERE bm.group_id=g.id AND bu.kind='bot') AS members,
       (SELECT COUNT(*) FROM chat_members om JOIN users ou ON ou.id = om.user_id WHERE om.group_id = g.id AND ou.kind='user' AND ou.last_seen > ?3) AS online,
       (SELECT COUNT(*) FROM (SELECT 1 FROM chat_messages m WHERE m.group_id = g.id AND m.id > MAX(cm.last_read,${CHAT_HISTORY_FLOOR}-1) AND m.created_at>=cm.joined_at AND m.deleted = 0 AND m.user_id != ?1 LIMIT 100)) AS unread,
       (SELECT COUNT(*) FROM (SELECT 1 FROM chat_messages m INDEXED BY idx_chat_msg_at_unread WHERE m.group_id = g.id AND m.id > MAX(cm.last_read,${CHAT_HISTORY_FLOOR}-1) AND m.deleted = 0 AND m.user_id != ?1
          AND m.created_at>=cm.joined_at AND instr(m.body,'@') > 0 AND m.body LIKE ?2 ESCAPE '\\' LIMIT 20)) AS at_me,
       l.id AS last_id, l.body AS last_body, l.image_key AS last_image, l.deleted AS last_deleted, l.created_at AS last_at,
       lu.username AS last_by, lu.name AS last_by_name
     FROM chat_members cm JOIN chat_groups g ON g.id = cm.group_id
     LEFT JOIN chat_messages l ON l.id = (SELECT MAX(id) FROM chat_messages WHERE group_id = g.id) AND l.created_at>=cm.joined_at AND l.id>=${CHAT_HISTORY_FLOOR}
     LEFT JOIN users lu ON lu.id = l.user_id
     WHERE cm.user_id = ?1 ORDER BY g.is_default DESC, COALESCE(l.created_at, g.created_at) DESC`).bind(u.id, `%@${likeEsc(u.username)}%`, now() - 300).all();
	const dmUnread = await c.env.DB.prepare(`SELECT COUNT(*) AS n FROM (
    SELECT m.id FROM dm_threads t JOIN dm_messages m INDEXED BY idx_dm_messages_thread
      ON m.thread_id=t.id AND m.id>t.read_low
    WHERE t.user_low=?1 AND t.last_message_id>t.read_low AND m.sender_id<>?1
    UNION ALL
    SELECT m.id FROM dm_threads t JOIN dm_messages m INDEXED BY idx_dm_messages_thread
      ON m.thread_id=t.id AND m.id>t.read_high
    WHERE t.user_high=?1 AND t.last_message_id>t.read_high AND m.sender_id<>?1
    LIMIT 100
  )`).bind(u.id).first();
	return c.json({
		can_manage: isChatAdmin(u),
		can_create: false,
		dm_unread: dmUnread?.n ?? 0,
		gone: gone.results.map((x) => ({
			id: x.id,
			name: x.name,
			is_default: !!x.is_default,
			kind: x.kind === "left" ? "left" : x.kind ? "kick" : "new",
			req: x.req,
			req_at: x.req_at,
			idle: !!x.idle,
			internal: !!x.internal
		})),
		groups: results.map((g) => ({
			id: g.id,
			name: g.name,
			avatar: g.avatar || null,
			is_default: !!g.is_default,
			internal: g.internal_open != null,
			apply_open: !!g.internal_open,
			owner_ctl: g.internal_open != null && isOwner(c, u),
			members: g.members,
			online: g.online,
			unread: g.unread,
			at_me: g.at_me,
			muted: !!g.muted,
			last_read: g.last_read,
			notice: g.notice || null,
			notice_at: g.notice_at || null,
			reqs: pm.get(g.id) ?? 0,
			latest: g.last_id ? {
				id: g.last_id,
				at: g.last_at,
				by: g.last_by_name || g.last_by,
				text: g.last_deleted ? "[消息已撤回]" : chatPreview(g.last_body ?? "") || (g.last_image ? "[图片]" : "")
			} : null
		}))
	});
});
async function addMembers(c, gid, names) {
	const list = JSON.stringify([...new Set(names.map((s) => String(s).trim().replace(/^@/, "")).filter(Boolean))].slice(0, 200));
	const [found, , , ins] = await c.env.DB.batch([
		c.env.DB.prepare("SELECT username FROM users WHERE kind='user' AND username COLLATE NOCASE IN (SELECT value FROM json_each(?))").bind(list),
		c.env.DB.prepare(`DELETE FROM chat_bans WHERE group_id = ? AND user_id IN
      (SELECT id FROM users WHERE kind='user' AND username COLLATE NOCASE IN (SELECT value FROM json_each(?)))`).bind(gid, list),
		c.env.DB.prepare(`DELETE FROM chat_join_reqs WHERE group_id = ? AND user_id IN
      (SELECT id FROM users WHERE kind='user' AND username COLLATE NOCASE IN (SELECT value FROM json_each(?)))`).bind(gid, list),
		c.env.DB.prepare(`INSERT OR IGNORE INTO chat_members (group_id, user_id, joined_at, last_read)
       SELECT ?1, id, ?2, (SELECT COALESCE(MAX(m.id), 0) FROM chat_messages m WHERE m.group_id = ?1)
       FROM users WHERE kind='user' AND username COLLATE NOCASE IN (SELECT value FROM json_each(?3)) RETURNING user_id`).bind(gid, now(), list)
	]);
	const have = new Set(found.results.map((r) => r.username.toLowerCase()));
	return {
		added: ins.results.length,
		missing: JSON.parse(list).filter((n) => !have.has(n.toLowerCase()))
	};
}
var groupId = (c) => intIn(c.req.param("id"), 0, Number.MAX_SAFE_INTEGER, 0);
app.post("/api/chat/groups", async (c) => {
	needSiteAdmin(c);
	fail(403, "新建群聊已关闭");
});
app.patch("/api/chat/groups/:id", async (c) => {
	needAdmin(c);
	if (await b33Internal(c.env.DB, groupId(c)) && !isOwner(c, c.get("user"))) fail(403, "只有站长能管理这个群");
	const name = String((await jsonBody(c)).name ?? "").trim().slice(0, 20);
	if (!name) fail(400, "群名不能为空");
	if (!(await c.env.DB.prepare("UPDATE chat_groups SET name = ? WHERE id = ?").bind(name, groupId(c)).run()).meta.changes) fail(404, "群不存在");
	return c.json({ ok: true });
});
// 群头像：群管理员（和改群名同一权限）上传本人的图片（/api/uploads for=avatar 得到 a/... key）；key 为空恢复站标
app.put("/api/chat/groups/:id/avatar", async (c) => {
	const u = needAdmin(c), gid = groupId(c), db = c.env.DB;
	if (await b33Internal(db, gid) && !isOwner(c, u)) fail(403, "只有站长能管理这个群");
	const g = await db.prepare("SELECT avatar FROM chat_groups WHERE id = ?").bind(gid).first();
	if (!g) fail(404, "群不存在");
	const b = await boundedJson(c), key = b.key == null || b.key === "" ? null : String(b.key);
	if (key === null) {
		await db.prepare("UPDATE chat_groups SET avatar = NULL WHERE id = ?").bind(gid).run();
		return c.json({ ok: true, avatar: null });
	}
	if (!/^a\/\d{4}\/\d{2}\/[a-f0-9]{24}\.(?:png|jpg|gif|webp)$/.test(key)) fail(400, "请选择本人上传的图片");
	const avatar = "/img/" + key;
	if (g.avatar === avatar) return c.json({ ok: true, avatar });
	if (!await db.prepare("SELECT 1 FROM uploads WHERE key=? AND user_id=? AND used=0 AND mime IN ('image/png','image/jpeg','image/gif','image/webp') AND size<=5242880").bind(key, u.id).first()) fail(400, "图片上传已失效，请重新选择");
	try {
		await commitUploadContent(db, u.id, [key], [db.prepare("UPDATE chat_groups SET avatar = ? WHERE id = ?").bind(avatar, gid)]);
	} catch (e) {
		if (String(e).includes("upload_claim_conflict") || String(e).includes("malformed JSON")) fail(409, "图片已被使用，请重新选择");
		throw e;
	}
	return c.json({ ok: true, avatar });
});
app.delete("/api/chat/groups/:id", async (c) => {
	needSiteAdmin(c);
	const gid = groupId(c);
	const g = await c.env.DB.prepare("SELECT is_default FROM chat_groups WHERE id = ?").bind(gid).first();
	if (!g) fail(404, "群不存在");
	if (gid === 1 || g.is_default) fail(400, "迷友群不能解散");
	const { results: imgs } = await c.env.DB.prepare("SELECT image_key, media FROM chat_messages WHERE group_id = ? AND image_key IS NOT NULL").bind(gid).all();
	const keys = [...new Set(imgs.flatMap((r) => [r.image_key, ...mediaKeys(msgMedia(r) ?? [])]))];
	await c.env.DB.batch([
		c.env.DB.prepare("UPDATE road_items SET source_hidden = 1, updated_at = ? WHERE source_group_id = ?").bind(now(), gid),
		c.env.DB.prepare("DELETE FROM chat_reactions WHERE message_id IN (SELECT id FROM chat_messages WHERE group_id = ?)").bind(gid),
		c.env.DB.prepare("DELETE FROM chat_boosts WHERE message_id IN (SELECT id FROM chat_messages WHERE group_id = ?)").bind(gid),
		c.env.DB.prepare("DELETE FROM chat_messages WHERE group_id = ?").bind(gid),
		c.env.DB.prepare("DELETE FROM chat_members WHERE group_id = ?").bind(gid),
		c.env.DB.prepare("DELETE FROM chat_groups WHERE id = ?").bind(gid)
	]);
	for (let i = 0; i < keys.length; i += 1e3) await c.env.BUCKET.delete(keys.slice(i, i + 1e3));
	return c.json({ ok: true });
});
