app.delete("/api/chat/groups/:id/members/:uid", async (c) => {
	const u = needUser(c);
	const gid = groupId(c);
	const uid = intIn(c.req.param("uid"), -Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER, 0);
	if (uid !== u.id && !isChatAdmin(u)) fail(403, "只有管理员能移出别人");
	if (uid !== u.id && await b33Internal(c.env.DB, gid) && !isOwner(c, u)) fail(403, "只有站长能管理这个群");
	if (!await c.env.DB.prepare("SELECT is_default FROM chat_groups WHERE id = ?").bind(gid).first()) fail(404, "群不存在");
	if (uid !== u.id) {
		const t = await c.env.DB.prepare("SELECT is_admin, role FROM users WHERE id = ?").bind(uid).first();
		if (t?.is_admin) fail(400, "不能移出管理员");
		if (t?.role === "gadmin" && !u.is_admin) fail(400, "群管只能由管理员移出");
	}
	await c.env.DB.batch([
		c.env.DB.prepare("DELETE FROM chat_members WHERE group_id = ? AND user_id = ?").bind(gid, uid),
		c.env.DB.prepare("INSERT OR REPLACE INTO chat_bans (group_id, user_id, created_at, kind) VALUES (?, ?, ?, ?)").bind(gid, uid, now(), uid === u.id ? "left" : "kick"),
		c.env.DB.prepare("DELETE FROM chat_join_reqs WHERE group_id = ? AND user_id = ?").bind(gid, uid)
	]);
	return c.json({ ok: true });
});
app.post("/api/chat/groups/:id/join-req", async (c) => {
	const u = needUser(c);
	const gid = groupId(c);
	const ban = await c.env.DB.prepare("SELECT kind FROM chat_bans WHERE group_id = ? AND user_id = ?").bind(gid, u.id).first();
	const group = await c.env.DB.prepare("SELECT is_default FROM chat_groups WHERE id=?").bind(gid).first();
	const b33p = group ? await c.env.DB.prepare("SELECT open_apply FROM chat_group_policy WHERE group_id=?").bind(gid).first() : null;
	if (!group || !group.is_default && !ban && !b33p) fail(404, "这个群不开放申请");
	if (b33p && (ban || !b33p.open_apply)) fail(404, "这个群不开放申请");
	if (await c.env.DB.prepare("SELECT 1 FROM chat_members WHERE group_id=? AND user_id=?").bind(gid, u.id).first()) return c.json({
		ok: true,
		joined: true
	});
	if ((await boundedJson(c, 1e3)).adult_content_ack !== true) fail(400, "请先确认已成年，并了解群内可能包含没品、变态、地狱笑话及18禁内容");
	const b31Idle = ban?.kind === "kick" ? await c.env.DB.prepare("SELECT 1 FROM chat_kick_notes n JOIN chat_bans b ON b.group_id=n.group_id AND b.user_id=n.user_id WHERE n.group_id=? AND n.user_id=? AND n.at>=b.created_at LIMIT 1").bind(gid, u.id).first() : null;
	const b32Held = (u.trust_level ?? 0) >= 4 && !isOwner(c, u);
	if (!b32Held && !b33p && (!ban || ban.kind === "left" || b31Idle)) {
		await addMembers(c, gid, [u.username]);
		if (await c.env.DB.prepare("SELECT 1 FROM chat_members WHERE group_id=? AND user_id=?").bind(gid, u.id).first()) return c.json({ ok: true, joined: true });
	}
	const r = await c.env.DB.prepare("SELECT status, created_at FROM chat_join_reqs WHERE group_id = ? AND user_id = ?").bind(gid, u.id).first();
	if (r?.status === 0) return c.json({
		ok: true,
		req: 0
	});
	if (r?.status === 2 && now() - r.created_at < 600) fail(429, "刚申请过，过一会儿再试");
	await c.env.DB.prepare(`INSERT INTO chat_join_reqs (group_id, user_id, status, created_at) VALUES (?, ?, 0, ?)
     ON CONFLICT (group_id, user_id) DO UPDATE SET status = 0, created_at = excluded.created_at`).bind(gid, u.id, now()).run();
	return c.json({
		ok: true,
		req: 0
	});
});
app.get("/api/chat/groups/:id/outside", async (c) => {
	needAdmin(c);
	if (await b33Internal(c.env.DB, groupId(c)) && !isOwner(c, c.get("user"))) fail(403, "只有站长能管理这个群");
	const gid = groupId(c);
	if (c.req.query("view") === "membership") {
		const group = await c.env.DB.prepare("SELECT is_default FROM chat_groups WHERE id=?").bind(gid).first();
		if (!group) fail(404, "群不存在");
		const before = intIn(c.req.query("before"), -Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER);
		const kind = c.req.query("kind") || "";
		if (["req", "new", "left", "kick"].includes(kind)) {
			const live = "u.kind='user' AND u.disabled=0 AND NOT EXISTS(SELECT 1 FROM chat_members m WHERE m.group_id=?1 AND m.user_id=u.id) AND NOT EXISTS(SELECT 1 FROM account_retirements a WHERE a.source_id=u.id)";
			const cols = "u.id,u.username,u.name,u.avatar,u.created_at,COALESCE(b.kind,'new') AS kind,b.created_at AS gone_at,r.status AS req,r.created_at AS req_at";
			let rows, next = null;
			if (kind === "req") rows = (await c.env.DB.prepare(`SELECT ${cols} FROM chat_join_reqs r JOIN users u ON u.id=r.user_id LEFT JOIN chat_bans b ON b.user_id=u.id AND b.group_id=?1
        WHERE r.group_id=?1 AND r.status=0 AND ${live} ${isOwner(c, c.get("user")) ? "" : "AND COALESCE(u.trust_level,0)<4"} ORDER BY r.created_at DESC LIMIT 500`).bind(gid).all()).results;
			else if (kind === "new") {
				rows = group.is_default ? (await c.env.DB.prepare(`SELECT ${cols} FROM users u LEFT JOIN chat_bans b ON b.user_id=u.id AND b.group_id=?1 LEFT JOIN chat_join_reqs r ON r.user_id=u.id AND r.group_id=?1
        WHERE u.id<?2 AND b.user_id IS NULL AND (r.user_id IS NULL OR r.status<>0) AND ${live} ORDER BY u.id DESC LIMIT 201`).bind(gid, before).all()).results
					: (await c.env.DB.prepare(`SELECT ${cols} FROM chat_join_reqs r JOIN users u ON u.id=r.user_id LEFT JOIN chat_bans b ON b.user_id=u.id AND b.group_id=?1
        WHERE r.group_id=?1 AND r.status<>0 AND b.user_id IS NULL AND u.id<?2 AND ${live} ORDER BY u.id DESC LIMIT 201`).bind(gid, before).all()).results;
				if (rows.length > 200) { next = rows[199].id; rows = rows.slice(0, 200); }
			} else {
				rows = (await c.env.DB.prepare(`SELECT ${cols} FROM chat_bans b JOIN users u ON u.id=b.user_id LEFT JOIN chat_join_reqs r ON r.user_id=u.id AND r.group_id=?1
        WHERE b.group_id=?1 AND b.kind=?3 AND u.id<?2 AND ${live} ORDER BY u.id DESC LIMIT 201`).bind(gid, before, kind).all()).results;
				if (rows.length > 200) { next = rows[199].id; rows = rows.slice(0, 200); }
			}
			const counts = await c.env.DB.prepare("SELECT (SELECT COUNT(*) FROM chat_join_reqs r WHERE r.group_id=?1 AND r.status=0 AND NOT EXISTS(SELECT 1 FROM chat_members m WHERE m.group_id=?1 AND m.user_id=r.user_id)) req,(SELECT COUNT(*) FROM chat_bans WHERE group_id=?1 AND kind='left') left_n,(SELECT COUNT(*) FROM chat_bans WHERE group_id=?1 AND kind='kick') kick_n").bind(gid).first();
			return c.json({ now: now(), kind, users: rows, next_before: next, counts: { req: counts?.req ?? 0, left: counts?.left_n ?? 0, kick: counts?.kick_n ?? 0 } });
		}
		const { results } = await c.env.DB.prepare(`SELECT u.id,u.username,u.name,u.avatar,u.created_at,
      COALESCE(b.kind,'new') AS kind,b.created_at AS gone_at,r.status AS req,r.created_at AS req_at
      FROM users u LEFT JOIN chat_bans b ON b.user_id=u.id AND b.group_id=?1
      LEFT JOIN chat_join_reqs r ON r.user_id=u.id AND r.group_id=?1
      WHERE u.id<?2 AND u.kind='user' AND u.disabled=0
        AND NOT EXISTS(SELECT 1 FROM chat_members m WHERE m.group_id=?1 AND m.user_id=u.id)
        AND NOT EXISTS(SELECT 1 FROM account_retirements a WHERE a.source_id=u.id)
        AND (?3=1 OR b.user_id IS NOT NULL OR r.user_id IS NOT NULL)
      ORDER BY u.id DESC LIMIT 201`).bind(gid, before, group.is_default).all();
		return c.json({
			now: now(),
			users: results.slice(0, 200),
			next_before: results.length > 200 ? results[199].id : null
		});
	}
	const { results } = await c.env.DB.prepare(`SELECT u.id, u.username, u.name, u.avatar, u.trust_level, u.last_seen, b.kind, b.created_at AS gone_at, r.status AS req, r.created_at AS req_at
     FROM (SELECT user_id FROM chat_bans WHERE group_id=?1 UNION SELECT user_id FROM chat_join_reqs WHERE group_id=?1) candidates
     JOIN users u ON u.id=candidates.user_id LEFT JOIN chat_bans b ON b.user_id=u.id AND b.group_id=?1
     LEFT JOIN chat_join_reqs r ON r.user_id=u.id AND r.group_id=?1
     WHERE 1=1 AND u.kind='user' AND NOT EXISTS (SELECT 1 FROM chat_members m WHERE m.group_id = ?1 AND m.user_id = u.id)
     ORDER BY (r.status = 0) DESC, COALESCE(r.created_at, b.created_at) DESC LIMIT 300`).bind(gid).all();
	return c.json({
		now: now(),
		users: results
	});
});
