app.post("/api/puzzles/:id/solve", async (c) => {
	const u = needUser(c);
	const id = intIn(c.req.param("id"), 0, Number.MAX_SAFE_INTEGER, 0);
	const pz = await c.env.DB.prepare("SELECT * FROM puzzles WHERE id = ?").bind(id).first();
	if (!pz) fail(404, "谜题不存在");
	const p = pz;
	const view = async () => c.json({
		correct: true,
		puzzle: await puzzleView(c, p)
	});
	if (u.silenced) fail(403, "你在 linux.do 处于禁言状态");
	if (u.id === p.creator_id) fail(400, "不能解自己出的题");
	const [prev, layers] = await Promise.all([c.env.DB.prepare("SELECT solved_at, layer FROM puzzle_attempts WHERE puzzle_id = ? AND user_id = ?").bind(id, u.id).first(), loadLayers(c, p)]);
	if (prev?.solved_at) return view();
	if (p.ends_at && p.ends_at < now()) fail(400, "谜题已结束");
	if (p.max_winners > 0 && p.winners_count >= p.max_winners) fail(400, "名额已被抢完");
	if (!await c.env.DB.prepare(`INSERT INTO puzzle_attempts (puzzle_id, user_id, attempts) VALUES (?, ?, 1)
     ON CONFLICT(puzzle_id, user_id) DO UPDATE SET attempts = attempts + 1
       WHERE solved_at IS NULL
     RETURNING attempts`).bind(id, u.id).first()) return view();
	const cur = Math.min(prev?.layer ?? 0, layers.length - 1);
	const L = layers[cur];
	const answer = normAnswer(String((await jsonBody(c)).answer ?? ""));
	if (!JSON.parse(L.answers).includes(await sha256(p.salt + answer))) return c.json({ correct: false });
	const adv = await c.env.DB.prepare(`UPDATE puzzle_attempts SET attempts = attempts - 1, layer = layer + 1
     WHERE puzzle_id = ? AND user_id = ? AND layer = ? AND solved_at IS NULL RETURNING layer`).bind(id, u.id, cur).first();
	if (!adv) return view();
	if (adv.layer < layers.length) return c.json({
		correct: true,
		next: true,
		note: L.note,
		puzzle: await puzzleView(c, p)
	});
	const rollback = () => c.env.DB.prepare("UPDATE puzzle_attempts SET layer = ? WHERE puzzle_id = ? AND user_id = ?").bind(cur, id, u.id).run();
	let codeId = null;
	if (p.reward_type === "codes") {
		const code = await c.env.DB.prepare(`UPDATE puzzle_codes SET claimed_by = ?, claimed_at = ?
       WHERE id = (SELECT id FROM puzzle_codes WHERE puzzle_id = ? AND claimed_by IS NULL ORDER BY id LIMIT 1)
         AND claimed_by IS NULL
       RETURNING id`).bind(u.id, now(), id).first();
		if (!code) {
			await rollback();
			fail(400, "答对了，可惜兑换码已经被领完");
		}
		codeId = code.id;
		await c.env.DB.prepare("UPDATE puzzles SET winners_count = winners_count + 1 WHERE id = ?").bind(id).run();
	} else if (!await c.env.DB.prepare(`UPDATE puzzles SET winners_count = winners_count + 1
       WHERE id = ? AND (max_winners = 0 OR winners_count < max_winners) RETURNING winners_count`).bind(id).first()) {
		await rollback();
		fail(400, "答对了，可惜名额刚好被抢完");
	}
	await c.env.DB.prepare("UPDATE puzzle_attempts SET solved_at = ?, code_id = ? WHERE puzzle_id = ? AND user_id = ?").bind(now(), codeId, id, u.id).run();
	p.winners_count += 1;
	return view();
});
