async function withMeta(c, meta) {
	const page = await c.env.ASSETS.fetch(new URL("/index.html", c.req.url));
	const origin = new URL(c.req.url).origin;
	const img = new URL(meta.image || "/og-card-1200x630.png", origin).toString();
	const tags = [
		["og:type", "website"],
		["og:site_name", "尽欢"],
		["og:title", meta.title],
		["og:description", meta.desc],
		["og:url", c.req.url],
		...img ? [["og:image", img], ["twitter:card", "summary_large_image"]] : []
	].map(([k, v]) => `<meta ${k.startsWith("twitter") ? "name" : "property"}="${k}" content="${attr(v)}">`).join("");
	return new HTMLRewriter().on("title", { element: (el) => {
		el.setInnerContent("尽欢");
	} }).on("meta[name=\"description\"]", { element: (el) => {
		el.setAttribute("content", meta.desc);
	} }).on("head", { element: (el) => {
		el.append(tags, { html: true });
	} }).transform(new Response(page.body, { headers: {
		"content-type": "text/html; charset=utf-8",
		"cache-control": "no-cache"
	} }));
}
