	const upto = Math.min(max.n, intIn(b.upto, 0, Number.MAX_SAFE_INTEGER, max.n));
	const rows = (await c.env.DB.prepare("SELECT id, body, media, image_key, width, height FROM chat_messages WHERE id > ? AND id <= ? AND deleted = 0 ORDER BY id LIMIT 51").bind(after, upto).all()).results;
