  let plots=0,pens=0,helps=0;const newbie=viewAt-r.created_at<STEAL.newbieDays*86400;try{const s=JSON.parse(r.public_state);helps=helpTargets(s,viewAt,b12Available(me.state,'feed',0)).length;if(!newbie){s.plots?.forEach((_,i)=>{if(stealPlot(s,i,viewAt,u.id))plots++});s.barn?.forEach((_,i)=>{if(stealPen(s,i,viewAt,u.id))pens++})}}catch{}
  const left=myStealLeft(me.state,r.user_id),hl=helpLeft(me.state,r.user_id),canSteal=plots+pens>0&&left.owner>0&&left.today>0&&me.state.en>=STEAL.energy,canHelp=helps>0&&hl.owner>0&&hl.today>0&&me.state.en>=HELP.energy,level=petLevelOf(r.xp).level,marked=marks.has(r.user_id),key=[+marked,+(canSteal||canHelp),level,Number(r.updated_at)||0,r.user_id];
