// ---------- 11-07 b7 鱼彩 ----------
const SCRATCH = [{ name: '小鱼刮刮乐', price: 1000 }, { name: '金鲸刮刮乐', price: 10000 }];
// 倍数 → 概率（期望返还约 74%）
const SCRATCH_TABLE = [[1000, 0.00005], [50, 0.002], [10, 0.01], [5, 0.03], [2, 0.08], [1, 0.18]];
const LOTTO = { price: 500, max: 30, nums: 30, pick: 5, balls: 10 };
