            const until = Math.min(ctx.t, pen.f + 24 * 3600);
            b12TakeAnimal(pen,ctx.t,st.n);
            pen.m = Math.max(20, pen.m - 2);
            xp += WORLD.xp.collect;
            s.cnt.collect = count('collect') + 1;
