   if(x.rlm){if(now-x.rlm.t<6*3600)return fail('还在秘境里，先走完或撤出');rlmEnd(x,false,out)}if(x.rd?.d!==d)x.rd={d,n:0};if(x.rd.n>=RLM_DAILY)return fail('今天进秘境的次数用完了');if(x.en<RLM_EN)return fail('灵力不足（要 '+RLM_EN+'）');
