function xsAction(s,act,ctx){
 const a=String(act?.a||'');if(!/^xs[A-Z][a-z]+$/.test(a))return null;
 return {a,ok:false,msg:'大肥鱼修仙记已下线，存档已保留'};
 if(!s.xs||s.xs.v!==XS_RULES.XS_VERSION)s.xs=XS_RULES.newXs(ctx.t);
 const r=XS_RULES.act(s.xs,{a:a.slice(2).toLowerCase(),i:act.i,herb:typeof act.herb==='string'?act.herb:undefined,n:act.n,el:typeof act.el==='string'?act.el:undefined},ctx.t,ctx.rand||Math.random);
 const {ok,...rest}=r;return {...rest,a,ok:!!ok};
}
