petWorld.get('/api/pet/world/refund', async (c) => {
    const u = needUser(c), t = Math.floor(Date.now() / 1000);
    if (t >= WORLD_REFUND.until)
        return c.json({ available: false, until: WORLD_REFUND.until });
    const q = await worldRefundQuote(c.env.DB, u.id);
    return c.json({ available: q.played && !q.done, until: WORLD_REFUND.until, ...q, enough: q.coins + q.net >= 0 });
});
petWorld.post('/api/pet/world/refund', async (c) => {
    sameOrigin(c);
    const u = needUser(c), db = c.env.DB, t = Math.floor(Date.now() / 1000);
    if (t >= WORLD_REFUND.until)
        fail(403, '一键回收只在今天有效，已经过期了');
    const body = await boundedJson(c, 1024);
    const op = body.operation;
    if (!opOk(op))
        return fail(400, '操作编号无效');
    const [w, q] = await Promise.all([worldLoad(db, u.id, t), worldRefundQuote(db, u.id)]);
    if (q.done)
        return c.json({ already: true, ...q });
    if (!q.played)
        fail(400, '你还没在🌟🐟谷花过或赚过 D币，不需要回收');
    if (q.coins + q.net < 0)
        fail(409, `回收要扣回 ${-q.net} D币，余额不够`);
    const fresh = newWorld(t);
    if (w.state.gift)
        fresh.gift = w.state.gift; // 新人礼已经领过，重置后不能再领
    const gate = `EXISTS(SELECT 1 FROM pet_world WHERE user_id=?1 AND op=?2)`;
    const attempt = WORLD_REFUND.kind + ':' + WORLD_REFUND.ref;
    try {
        await db.batch([
            // 小岛重置：版本对不上（期间又买卖过）就整批回滚，让用户重新看一眼金额
            db.prepare(`UPDATE pet_world SET state=?3,rev=rev+1,op=?2,updated_at=?4 WHERE user_id=?1 AND rev=?5`).bind(u.id, op, JSON.stringify(fresh), t, w.rev),
            db.prepare(`SELECT json(CASE WHEN ${gate} THEN '1' ELSE 'conflict' END) AS ok`).bind(u.id, op),
            db.prepare(`INSERT OR IGNORE INTO coin52_wallets(user_id,balance,revision,updated_at) VALUES(?1,0,0,?2)`).bind(u.id, t),
            // 流水唯一（user_id,kind,ref）：已经回收过会直接报错回滚
            db.prepare(`INSERT INTO coin52_ledger(user_id,kind,ref,attempt,delta,balance_after,created_at) SELECT ?1,?3,?4,?5,?6,balance+?6,?7 FROM coin52_wallets WHERE user_id=?1 AND balance+?6>=0 AND ${gate}`).bind(u.id, op, WORLD_REFUND.kind, WORLD_REFUND.ref, attempt, q.net, t),
            db.prepare(`UPDATE coin52_wallets SET balance=balance+?3,revision=revision+1,updated_at=?4 WHERE user_id=?1 AND balance+?3>=0 AND EXISTS(SELECT 1 FROM coin52_ledger WHERE user_id=?1 AND attempt=?2 AND created_at=?4)`).bind(u.id, attempt, q.net, t),
            db.prepare(`SELECT json(CASE WHEN EXISTS(SELECT 1 FROM coin52_ledger WHERE user_id=?1 AND attempt=?2 AND created_at=?3) THEN '1' ELSE 'poor' END) AS ok`).bind(u.id, attempt, t),
        ]);
    }
    catch {
        return c.json({ error: '金额刚刚有变化（或余额不够），请重新打开看一下再确认', code: 'refund_conflict', ...(await worldRefundQuote(db, u.id)) }, 409);
    }
    const after = await worldLoad(db, u.id, t);
    return c.json({ ok: true, net: q.net, spent: q.spent, earned: q.earned, coins: q.coins + q.net, rev: after.rev, state: after.state });
});
// ---------- 2026-11-07 串门偷菜 + 大肥鱼守家（设计：research/pet-world-20261106/design.md §1–2） ----------
// 不加新表：每日次数记在访客自己的小岛状态（cnt，按现实日清零），「谁来过」记在主人的小岛状态（vis，最近 20 条）。
// 一次偷 = 守家擂台（petSimulate，主人 +10% 生命）+ 两个人的小岛状态同一批写入（互相校验版本号，任何一边变了整批回滚）。
async function b12GuardAttacker(db,id,name,attacker,defender,t){
 const real=petLevelOf(attacker?.total_xp||0).level,home=petLevelOf(defender?.total_xp||0).level;
 if(real-home<=3||petXpBoost(defender?.total_xp||0,t).tier===0)return fighterFor(db,id,name,attacker);
 const level=home+1;await grantLevelRewards(db,id,real);
 const {gear,points}=await loadoutOf(db,id),valid=petValidPoints(points,real)?points:ZERO,total=Object.values(valid).reduce((sum,n)=>sum+n,0),budget=petPointsTotal(level);
 const limited=Object.fromEntries(Object.entries(valid).map(([key,n])=>[key,total>budget?Math.floor(n*budget/total):n]));
 const fighter=petFighter(id,name,level,limited,gear);
 if(fighter.wskill&&petSkillById(fighter.wskill)?.level>level)delete fighter.wskill;
 return {...fighter,realLevel:real,assist:true};
}

const STEAL = { protect: 1800, perPlot: 2, perPen: 2, daily: 999, perOwner: 999, energy: 5, perSpot: 1, energyMax: 15, newbieDays: 1, fineMax: 5000, fineDaily: 20000, homeHp: 1.1, caught: 0.55, active: 3 * 86400 };
const stealPlot = (s, i, t, vid) => {
    const p = s.plots?.[i];
    if (!p)
        return null;
    const weather = weatherOf(isleDay(t)), st = cropStage(p, t, sprinkled(s, i) || weather === 1);
    if (!st || st.stage !== 3)
        return null;
    const sv = p.sv || [];
    if (t - (p.t + st.total) < STEAL.protect || sv.length >= STEAL.perPlot || sv.includes(vid))
        return null;
    return { id: p.c, price: BASE_PRICE[p.c] || 0 };
};
const stealPen = (s, i, t, vid) => {
    const pen = s.barn?.[i];
    if (!pen)
        return null;
    const st = animalReady(pen, t), day = worldDay(t), sv = pen.svd === day ? pen.sv || [] : [];
    // 窝里至少攒了 2 个才能偷（主人至少留 1 个）；最早那个产出已经超过 30 分钟
    if (st.n < 2 || sv.length >= STEAL.perPen || sv.includes(vid) || t - st.firstReady < STEAL.protect)
        return null;
    return { id: st.def.product, price: BASE_PRICE[st.def.product] || 0 };
};
const publicIsle = (s, t, vid) => ({
    plots: (s.plots || []).map((p, i) => { if (!p)
        return null; const st = cropStage(p, t, sprinkled(s, i) || weatherOf(isleDay(t)) === 1); return { c: p.c, stage: st?.stage ?? 0, left: st?.left ?? 0, steal: !!stealPlot(s, i, t, vid), stolen: (p.sv || []).length }; }),
    barn: (s.barn || []).map((pen, i) => { const st = animalReady(pen, t); return { k: pen.k, n: st.n, fed: st.fed, steal: !!stealPen(s, i, t, vid) }; }),
    house: s.tools?.house ?? 0, plotN: s.plotN, barnN: s.barnN,
});
async function visitOwner(db, id, t) {
    const r = await db.prepare(`SELECT w.rev,w.state,u.id,u.username,u.name,u.nick,u.avatar,u.created_at FROM pet_world w JOIN users u ON u.id=w.user_id
    WHERE w.user_id=? AND u.disabled=0 AND u.kind='user' AND NOT EXISTS(SELECT 1 FROM account_retirements a WHERE a.source_id=u.id)`).bind(id).first();
    if (!r)
        return null;
    const state = JSON.parse(r.state);
    if (state.v !== 2)
        return null;
    return { rev: r.rev, state: refresh(state, t), user: r, name: r.nick || r.name || r.username, newbie: t - r.created_at < STEAL.newbieDays * 86400 };
}
// 做客时渲染对方岛用的状态：只给地块 / 畜栏 / 蟹笼 / 建筑等级，不给背包、余额、记录；体力换成访客自己的
const visitState = (s, myEn, t) => ({ v: 2, en: myEn, enT: t, enDay: worldDay(t), plotN: s.plotN, plots: (s.plots || []).map((p) => p && { c: p.c, t: p.t, w: p.w, g: p.g, h: p.h, sv: p.sv }), barnN: s.barnN,
    barn: (s.barn || []).map((p) => ({ k: p.k, f: p.f, p: p.p, m: p.m, born:p.born, held:p.held, heldAt:p.heldAt })), traps: s.traps || [], tools: s.tools, inv: {}, mine: { max: 1 }, earn: { day: worldDay(t), amt: 0 }, cnt: {}, log: 0, gift: 1 });
const myStealLeft = (s, ownerId) => ({ today: Math.max(0, STEAL.daily - (s.cnt?.steal || 0)), owner: Math.max(0, STEAL.perOwner - (s.cnt?.['st' + ownerId] || 0)) });
