petWorld.post('/api/pet/world/board/:id{[0-9]+}', async (c) => {
    sameOrigin(c);
    const u = needUser(c), db = c.env.DB, id = Number(c.req.param('id')), t = Math.floor(Date.now() / 1000);
    const body = await boundedJson(c, 2048);
    if (!opOk(body.operation))
        fail(400, '操作编号无效');
    const removing = typeof body.remove === 'string';
    const text = typeof body.text === 'string' ? body.text.replace(/[\u0000-\u0008\u000b-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2066-\u2069]/g, '').trim() : '';
    if (!removing && (!text || [...text].length > BOARD.length))
        fail(400, '留言请填写1至200个字');
    if (removing && !opOk(body.remove))
        fail(400, '留言编号无效');
    const o = await visitOwner(db, id, t);
    if (!o)
        fail(404, 'TA 还没有小岛');
    const os = o.state;
    let vs = null, me = null;
    if (removing) {
        const message = (os.board || []).find((m) => m.id === body.remove);
        if (!message)
            return c.json({ ok: true, duplicate: true, messages: boardMessages(os, u.id, id) });
        if (u.id !== id && message.author !== u.id)
            fail(403, '只能删除自己的留言；岛主可管理本岛留言');
        os.board = os.board.filter((m) => m.id !== body.remove);
    }
    else {
        me = id === u.id ? { rev: o.rev, state: os } : await worldLoad(db, u.id, t);
        vs = me.state;
        if ((os.board || []).some((m) => m.id === body.operation && m.author === u.id) || (vs.boardOps || []).some((m) => m.op === body.operation && m.owner === id) || (vs.boardLast?.op === body.operation && vs.boardLast?.owner === id))
            return c.json({ ok: true, duplicate: true, messages: boardMessages(os, u.id, id) });
        if (vs.boardLast && t - vs.boardLast.t < BOARD.gap)
            return c.json({ error: '留言太快了，请一分钟后再发', code: 'board_slow' }, 429);
        os.board = [{ id: body.operation, author: u.id, name: displayName(u).slice(0, 40), text, t }, ...(os.board || [])].slice(0, BOARD.max);
        vs.boardLast = { op: body.operation, owner: id, t };
        vs.boardOps = [vs.boardLast, ...(vs.boardOps || [])].slice(0, 32);
    }
    const oRaw = JSON.stringify(os), vRaw = vs ? JSON.stringify(vs) : null;
    if (new TextEncoder().encode(oRaw).length > 48 * 1024 || (vRaw && new TextEncoder().encode(vRaw).length > 48 * 1024))
        fail(413, '小岛数据过大，请先整理留言或背包');
    if (removing || id === u.id) {
        const r = await db.prepare('UPDATE pet_world SET state=?3,rev=rev+1 WHERE user_id=?1 AND rev=?2').bind(id, o.rev, oRaw).run();
        if (!r.meta.changes)
            return c.json({ error: '小岛刚有变化，请重试', code: 'world_conflict' }, 409);
    }
    else {
        try {
            await db.batch([
                db.prepare('UPDATE pet_world SET state=?3,rev=rev+1 WHERE user_id=?1 AND rev=?2 AND EXISTS(SELECT 1 FROM pet_world WHERE user_id=?4 AND rev=?5)').bind(id, o.rev, oRaw, u.id, me.rev),
                db.prepare('UPDATE pet_world SET state=?3,rev=rev+1 WHERE user_id=?1 AND rev=?2 AND EXISTS(SELECT 1 FROM pet_world WHERE user_id=?4 AND rev=?5)').bind(u.id, me.rev, vRaw, id, o.rev + 1),
                // json(invalid)会中止D1原子批次，防止只写成功一边。
                db.prepare("SELECT json(CASE WHEN EXISTS(SELECT 1 FROM pet_world WHERE user_id=?1 AND rev=?2) AND EXISTS(SELECT 1 FROM pet_world WHERE user_id=?3 AND rev=?4) THEN '1' ELSE 'conflict' END)").bind(id, o.rev + 1, u.id, me.rev + 1),
            ]);
        }
        catch {
            return c.json({ error: '小岛刚有变化，请重试', code: 'world_conflict' }, 409);
        }
    }
    return c.json({ ok: true, messages: boardMessages(os, u.id, id) });
});
