      sameOrigin(c);
      const user = needUser(c), id = game(c.req.param("game")), body = await boundedJson(c, 8192);
      if (body.user_id !== user.id) fail(403, "\u767B\u5F55\u8D26\u53F7\u5DF2\u53D8\u5316\uFF0C\u8BF7\u91CD\u65B0\u8FDB\u5165\u6E38\u620F", "arcade_account_changed");
