      emit("castDone", { key: cast.key, name: cast.name, emoji: cast.emoji });
      const ps = getPlayerStats();
      const key2 = cast.key;
      const finalMult = m.isFinal ? CONFIG.boss.finalSkillMult || 1 : 1;
      const mech = mechOf(m);
      if (mech && mech.type === "drain") {
        const drained = Math2.min(state.rage, mech.rage);
        state.rage -= drained;
        const heal = Math2.round(m.maxHp * mech.healPct);
        m.hp = Math2.min(m.maxHp, m.hp + heal);
        addLog2(`\u{1F300} ${m.name} \u541E\u566C\u4E86\u4F60 ${drained} \u70B9\u6012\u6C14\uFF0C\u5E76\u56DE\u590D ${heal} \u70B9\u751F\u547D\uFF01`, "boss", "boss");
      }
