        addLog2(`\u{1F9CA} \u4F60\u88AB ${m.name} \u51BB\u7ED3\u4E86 ${mech.durSec} \u79D2\uFF0C\u671F\u95F4\u65E0\u6CD5\u884C\u52A8\u4E14\u53D7\u4F24 +${Math2.round((mech.dmgTaken - 1) * 100)}%\uFF01`, "boss", "boss");
        emit("frozen", { sec: mech.durSec });
